begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();


  values ('b2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000001', 1, 'Liability', 'I agree.',
          encode(extensions.digest(convert_to('I agree.', 'UTF8'), 'sha256'), 'hex'));
    waiver_version_ids, opens_at, closes_at, created_by)
  values ('e1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-00000000000a', 'Fall season', 'fall-season-2026', 'season', 'open', 2, true,
    'f2000000-0000-0000-0000-000000000001', array['b2000000-0000-0000-0000-000000000001']::uuid[],
    now() - interval '1 day', now() + interval '30 days', 'a1111111-1111-1111-1111-111111111111');
    guardian_relationship, player_first_name, player_last_name, player_date_of_birth, form_version_id, answers, status)
  values
  ('d1000000-0000-0000-0000-000000000001', 'e1000000-0000-0000-0000-000000000001', private.next_registration_display_id(), 'a4444444-4444-4444-4444-444444444444',
    '11000000-0000-0000-0000-000000000001', 'Pat Parent', 'Pat@Example.test', 'Mother', 'Ava', 'Adams', current_date - interval '10 years',
    'f2000000-0000-0000-0000-000000000001', '{"shirt":"s"}', 'submitted'),
  ('d2000000-0000-0000-0000-000000000002', 'e1000000-0000-0000-0000-000000000001', private.next_registration_display_id(), 'a8888888-8888-8888-8888-888888888888',
    '22000000-0000-0000-0000-000000000002', 'Paula Parent', 'paula@example.test', 'Mother', 'Pia', 'Park', current_date - interval '9 years',
    'f2000000-0000-0000-0000-000000000001', '{"shirt":"m"}', 'submitted');

reset role;
select lives_ok($$ update public.registration_events set info_blocks = '[{"type":"description","title":"Hi","body":"Hello"},{"type":"key_facts","items":[{"label":"When","value":"Sat"}]},{"type":"agenda","items":[{"time":"9","label":"Warm up"}]},{"type":"what_to_bring","items":["Water"]},{"type":"faq","items":[{"question":"Q","answer":"A"}]}]' where id = 'e4000000-0000-0000-0000-000000000004' $$, 'typed blocks are accepted');
select throws_ok($$ update public.registration_events set info_blocks = '[{"type":"description","body":"x","onclick":"alert(1)"}]' where id = 'e4000000-0000-0000-0000-000000000004' $$, '23514', 'invalid_info_block', 'unknown keys are refused at the database');
select throws_ok($$ update public.registration_events set info_blocks = '[{"type":"description","body":{"html":"<script>"}}]' where id = 'e4000000-0000-0000-0000-000000000004' $$, '23514', 'invalid_info_block', 'non-string values are refused');
select throws_ok($$ update public.registration_events set info_blocks = '[{"type":"faq","items":[{"question":"Q","answer":"A","extra":"x"}]}]' where id = 'e4000000-0000-0000-0000-000000000004' $$, '23514', 'invalid_info_block', 'unknown item keys are refused');
select throws_ok($$ update public.registration_events set info_blocks = '[{"type":"what_to_bring","items":[{"a":1}]}]' where id = 'e4000000-0000-0000-0000-000000000004' $$, '23514', 'invalid_info_block', 'item shapes are checked');
select throws_ok($$ update public.registration_events set info_blocks = ('[{"type":"description","body":"' || repeat('x', 9000) || '"}]')::jsonb where id = 'e4000000-0000-0000-0000-000000000004' $$, '23514', 'invalid_info_block', 'long strings are refused');
select lives_ok($$ update public.registration_events set cover_image_path = 'a1000000-0000-0000-0000-00000000000a/cover.png' where id = 'e4000000-0000-0000-0000-000000000004' $$, 'a cover under the issuer''s prefix is accepted');
select throws_ok($$ update public.registration_events set cover_image_path = 'a2000000-0000-0000-0000-00000000000b/cover.png' where id = 'e4000000-0000-0000-0000-000000000004' $$, '23514', 'invalid_cover_path', 'a cover under another team''s prefix is refused');

select * from finish();
rollback;
